def transform(grid):
    """Shift the entire grid down by one row, filling the top with its background color."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for color in row:
            counts[color] = counts.get(color, 0) + 1
    background = max(counts, key=counts.get)
    return [[background] * w] + [row[:] for row in grid[:-1]]
